fn solve(n: i8) -> Vec<char> {
    // The input n is guaranteed to be a three-digit number in [100, 999].
    // We convert it to string to get its decimal digits easily.
    // Then combine with ['A', 'B', 'C'] prefix to form the six-character vector.
    
    let digits_str = n.to_string(); // e.g. "123"
    let mut result = Vec::with_capacity(6);

    // Add prefix characters 'A', 'B', 'C'
    result.push('A');
    result.push('B');
    result.push('C');

    // Append the decimal digits as characters
    for ch in digits_str.chars() {
        result.push(ch);
    }

    result
}